#include <Adafruit_NeoPixel.h>

#define LED_PIN 6
#define LED_COUNT 1

Adafruit_NeoPixel strip(LED_COUNT, LED_PIN, NEO_GRB + NEO_KHZ800);

void setup() {
strip.begin();
strip.setBrightness(3); // 初回なので極端に暗く
strip.clear();
strip.show();
}

void loop() {
// 先頭の1個だけ、弱く赤
strip.setPixelColor(0, strip.Color(20, 0, 0));
strip.show();
delay(1000);

// 消灯
strip.clear();
strip.show();
delay(1000);
}
